// Production entry for Docker/Railway/Hostinger. adapter-node assumes https unless a proxy
// sends a protocol header, so derive it from ORIGIN to support plain-http self-hosting too.
import { createServer } from 'node:http';
// @ts-expect-error generated by `pnpm build`
import { handler } from '../build/handler.js';

const origin = process.env.ORIGIN ? new URL(process.env.ORIGIN) : null;
const port = Number(process.env.PORT ?? 3000);
const host = process.env.HOST ?? '0.0.0.0';

const server = createServer((req, res) => {
	if (origin) req.headers['x-forwarded-proto'] = origin.protocol.slice(0, -1);
	// Direct connections (no proxy) still need a client IP for auth rate limiting.
	req.headers['x-forwarded-for'] ??= req.socket.remoteAddress;
	handler(req, res, () => {
		res.statusCode = 404;
		res.end('Not found');
	});
});

server.listen(port, host, () => console.log(`Listening on http://${host}:${port}`));

for (const signal of ['SIGTERM', 'SIGINT'] as const) {
	process.once(signal, () => {
		server.close(() => process.exit(0));
		server.closeIdleConnections();
		setTimeout(() => process.exit(0), 10_000).unref();
	});
}
